INSERT INTO honors (name_zh, name_en, desc_zh, desc_en, image, sort) VALUES
('综合资质证书','Certificates Overview','高新技术企业、安全生产标准化、SEC 年度确认及多项专利证书。','High-tech enterprise, work safety standardization, SEC annual confirmation and multiple patents.','honor-01.jpg',1),
('上海市“专精特新”中小企业','Shanghai \"Specialized & Innovative\" SME','上海市经济和信息化委员会认定,聚焦细分领域的专业化标杆。','Recognized by Shanghai SME Commission as a specialized and innovative enterprise.','honor-02.jpg',2),
('质量管理体系认证','QMS Certification','通过 SEC 质量管理体系认证,质量管理与国际接轨。','Certified quality management system (SEC), aligned with international standards.','honor-03.jpg',3),
('ISO Quality Certification','ISO Quality Certification','面向国际客户的质量管理体系认证(英文版)。','Quality management system certification for international clients.','honor-04.jpg',4),
('安全生产标准化三级企业','Work Safety Standardization Level 3','机械行业安全生产标准化三级企业认证。','Level-3 work safety standardization (machinery industry).','honor-05.jpg',5),
('实用新型专利证书','Utility Model Patents','拥有多项实用新型专利,覆盖光伏边框生产与检测设备。','Multiple utility model patents covering PV frame production and inspection equipment.','honor-06.jpg',6),
('专利登记簿副本','Patent Register','国家知识产权局专利登记簿副本,专利权属清晰可查。','Patent register copies from CNIPA with clear ownership records.','honor-07.jpg',7);
